#include <iostream>
#include <type_traits>
template <int N> 
constexpr int factorial() {
  return N <= 1 ? 1 : N * factorial<N - 1>();
}
int main() {
  constexpr int result = factorial<5>(); // Compile-time computation
  std::cout << result << std::endl;     // Output: 120
  static_assert(factorial<0>() == 1, "Factorial of 0 should be 1");
  return 0;
}
